// Payload del Studio: { event, networks, post: { id, caption, images:[{url,title,text}], isCarousel, links } }
// Cabecera X-Studio-Signature = HMAC-SHA256(body, N8N_WEBHOOK_SECRET) en hex. Verifícala aquí si lo necesitas.
const body = $json.body ?? $json;
if (body.event === 'ping') return [{ json: { results: [] } }];

const results = [];
for (const network of body.networks) {
  // TODO: reemplaza por los nodos de cada red (LinkedIn, TikTok, X…) o llama a sub-workflows.
  // Devuelve ok/externalId/permalink/error por red.
  results.push({ network, ok: true, externalId: `n8n-${network}-${Date.now()}` });
}
return [{ json: { results } }];
